import { calculations, choices, part, table } from './science-practice-tools.js';

function topic(number, simple, challenge, numerical = []) {
  const bank = 'chemistry-' + number;
  return [
    ...choices(bank, 'simple', simple),
    ...choices(bank, 'challenge', challenge),
    ...calculations(bank, numerical),
  ];
}

function diagram(caption, alt, drawing, height = 210) {
  return {
    caption,
    alt,
    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 ' + height + '" aria-hidden="true">' +
      '<g fill="#23344f" font-family="system-ui, sans-serif" font-size="16">' +
      drawing + '</g></svg>',
  };
}

